#include <iostream>
#include <vector>
#include <string>

using namespace std;

/**
 * Problem: 25081 - Solving Maze Problems
 * 
 * 解題思路：
 * 1. 在一個 10x10 的迷宮中，尋找從 'S' 到 'G' 的唯一路徑。
 * 2. 使用深度優先搜尋 (DFS) 尋找路徑，並在遞迴回溯時標記正確的路徑為 '+'。
 * 3. 因為題目保證只有一條路徑，且迷宮很小 (10x10)，DFS 非常適合。
 */

char maze_grid[10][10];
bool visited_grid[10][10];
int d_rows[] = {0, 0, 1, -1};
int d_cols[] = {1, -1, 0, 0};

bool find_path(int r, int c) {
    if (r < 0 || r >= 10 || c < 0 || c >= 10 || maze_grid[r][c] == '#' || visited_grid[r][c])
        return false;

    if (maze_grid[r][c] == 'G') return true;

    visited_grid[r][c] = true;
    for (int i = 0; i < 4; i++) {
        int nr = r + d_rows[i];
        int nc = c + d_cols[i];
        if (find_path(nr, nc)) {
            if (maze_grid[r][c] != 'S') maze_grid[r][c] = '+';
            return true;
        }
    }
    return false;
}

int main() {
    while (cin >> maze_grid[0][0]) {
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (i == 0 && j == 0) continue;
                cin >> maze_grid[i][j];
            }
        }

        int start_r, start_c;
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (maze_grid[i][j] == 'S') {
                    start_r = i; start_c = j;
                }
                visited_grid[i][j] = false;
            }
        }

        if (find_path(start_r, start_c)) {
            for (int i = 0; i < 10; i++) {
                for (int j = 0; j < 10; j++) cout << maze_grid[i][j];
                cout << endl;
            }
        } else {
            cout << "No solution" << endl;
        }
        cout << endl;
    }
    return 0;
}
